<section class="wrap flow-card"><span class="flow-icon">↗</span><h1><?= e($t('upgrade.title')) ?></h1><p><?= e($t('upgrade.intro')) ?></p>
<?php if($latestChange): ?><p><?= e($t('upgrade.history',['from'=>$latestChange['from_plan'],'to'=>$latestChange['to_plan']])) ?></p><p role="status"><?= e($t($latestChange['status']==='completed'?'upgrade.done':($latestChange['status']==='review'?'upgrade.review':(in_array($latestChange['status'],['cancelled','expired'],true)?'upgrade.cancelled':'upgrade.processing')))) ?></p>
<?php if(in_array($latestChange['status'],['creating','pending'],true)): ?><form method="post" action="<?= $url('upgrade') ?>"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="change_id" value="<?= e($latestChange['id']) ?>"><button class="button outline"><?= e($t('upgrade.cancel')) ?></button></form><?php endif ?><?php endif ?>
<?php if(!$upgradeOffers): ?><p><?= e($t('upgrade.unavailable')) ?></p><?php endif ?>
<?php foreach($upgradeOffers as $offer): $p=$offer['plan']; ?><article class="recovery"><h2><?= e($p['name'].' · '.$p['capacity']) ?></h2><p class="payment-mode-label"><?= e($t('billing.payment_mode_'.$p['stripe_mode'])) ?></p><p><?= e($t('upgrade.renewal',['amount'=>number_format($p['price_amount']/100,2,',',''),'date'=>Zion\SubscriptionChanges::displayDate($offer['renewal_at']),'interval'=>$t($p['billing_interval']==='year'?'billing.year.interval':'pricing.interval')])) ?></p><p><?= e($t('upgrade.deadline',['date'=>Zion\SubscriptionChanges::displayDate($offer['deadline'])])) ?></p><form method="post" action="<?= $url('upgrade') ?>"><input type="hidden" name="_csrf" value="<?= e(Zion\Security::csrf()) ?>"><input type="hidden" name="plan" value="<?= e($p['slug']) ?>"><button class="button full"><?= e($t('upgrade.pay',['amount'=>number_format($offer['amount']/100,2,',','')])) ?> ↗</button></form></article><?php endforeach ?>
<p><a class="text-link" href="<?= $url('status') ?>"><?= e($t('status.title')) ?></a></p></section>
